public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a string key
    java.util.function.Function<int[], String> key = arr -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(arr[i]);
        }
        return sb.toString();
    };

    String startKey = key.apply(start);
    String endKey = key.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) {
            continue; // invalid path entry, skip
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = key.apply(a);
        String bKey = key.apply(b);
        graph.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        graph.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS to check reachability
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String next : neighbors) {
            if (!visited.contains(next)) {
                if (next.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(next);
                queue.offer(next);
            }
        }
    }

    return "cannot be travelled";
}

