public String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    int n = arr.length;
    boolean[] used = new boolean[n];
    StringBuilder sb = new StringBuilder();
    int unused = n;
    while (unused > 0) {
        // ascending: pick smallest > last appended (effectively next unused). We just iterate forward.
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                sb.append(arr[i]);
                used[i] = true;
                unused--;
            }
        }
        // descending
        for (int i = n-1; i >= 0; i--) {
            if (!used[i]) {
                sb.append(arr[i]);
                used[i] = true;
                unused--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    java.util.Set<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // dp0 = cost to reach step i-2, dp1 = cost to reach step i-1
    int dp0 = 0, dp1 = 0;
    for (int i = 2; i <= n; i++) {
        // cost to step onto i-1 (previous step) or i-2 and then jump to i
        int costFromPrev1 = dp1 + cost[i - 1];
        int costFromPrev2 = dp0 + cost[i - 2];
        int dp2 = Math.min(costFromPrev1, costFromPrev2);
        dp0 = dp1;
        dp1 = dp2;
    }
    return dp1;
}

