public int minInsertions(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of inserted ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--; // match with an existing '('
            } else {
                // need an extra '(' before this ')'
                insertions++;
            }
        }
    }
    // remaining unmatched '(' need ')' after them
    return insertions + balance;
}

