private int dfs(int idx, java.util.Set<String> seen, String s) {
    if (idx == s.length()) return 0;
    int max = 0;
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int val = 1 + dfs(end, seen, s);
            if (val > max) max = val;
            seen.remove(sub);
        }
    }
    return max;
}

