public String getSmallestString(int n, int k) {
    // Minimum sum when all characters are 'a'
    int minSum = n;
    // If the target sum is less than the minimum, no string is possible
    // (problem constraints usually guarantee a valid input, but handle just in case)
    if (k < minSum) {
        return "";
    }
    // If the target sum equals the minimum, return all 'a's
    if (k == minSum) {
        return "a".repeat(n);
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - minSum; // how many extra values we need to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        // Each position can contribute at most 25 extra (from 'a' to 'z')
        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

