public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> res = new java.util.ArrayList<>();
    if (low == 0) {
        res.add(0);
    }

    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long curr = queue.poll();
        if (curr > high) continue;

        if (curr >= low) {
            res.add((int) curr);
        }

        long lastDigit = curr % 10;
        if (lastDigit > 0) {
            long next = curr * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = curr * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    java.util.Collections.sort(res);
    return res;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long curr = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (curr == 0) {
            count += higher * factor;
        } else if (curr == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

