public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top < 0) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int diag = 0; diag < m + n - 1; diag++) {
        if ((diag & 1) == 0) { // even diagonal, traverse from bottom to top
            int rowStart = Math.min(diag, m - 1);
            int rowEnd = Math.max(0, diag - (n - 1));
            for (int row = rowStart; row >= rowEnd; row--) {
                int col = diag - row;
                result[index++] = mat[row][col];
            }
        } else { // odd diagonal, traverse from top to bottom
            int rowStart = Math.max(0, diag - (n - 1));
            int rowEnd = Math.min(diag, m - 1);
            for (int row = rowStart; row <= rowEnd; row++) {
                int col = diag - row;
                result[index++] = mat[row][col];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the number to a mutable array of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the first index i (from right) where digits[i-1] < digits[i]
    int i = len - 1;
    while (i > 0 && digits[i - 1] >= digits[i]) {
        i--;
    }

    // If no such index exists, all digits are in non‑increasing order → no larger permutation
    if (i == 0) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of i-1 that is greater than digits[i-1]
    int j = len - 1;
    while (digits[j] <= digits[i - 1]) {
        j--;
    }

    // Step 3: Swap digits[i-1] and digits[j]
    char temp = digits[i - 1];
    digits[i - 1] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the subarray from i to the end to get the smallest possible suffix
    int left = i, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert the digit array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // In case the number exceeds the range of int
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[][] pairs = {{'0','0'},{'1','1'},{'8','8'},{'6','9'},{'9','6'}};
    char[] current = new char[n];
    build(result, current, 0, n - 1, pairs);
    return result;
}

private static void build(List<String> res, char[] s, int left, int right, char[][] pairs) {
    if (left > right) {
        res.add(new String(s));
        return;
    }
    if (left == right) {
        char[] middle = {'0', '1', '8'};
        for (char m : middle) {
            s[left] = m;
            res.add(new String(s));
        }
        return;
    }
    for (char[] p : pairs) {
        if (left == 0 && s.length > 1 && p[0] == '0') continue; // avoid leading zero
        s[left] = p[0];
        s[right] = p[1];
        build(res, s, left + 1, right - 1, pairs);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    long area = (long)(p2[0] - p1[0]) * (p3[1] - p1[1])
              - (long)(p3[0] - p1[0]) * (p2[1] - p1[1]);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0; // or throw an exception if preferred
    }
    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;

    for (int i = 1; i < n; i++) {
        int next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;

        if (next == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (next == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (next == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            current = 1;
        }
        if (current > max) {
            max = current;
        }
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9) {
            cur++;
        } else {
            while (cur / 10 > 0 && (cur / 10) % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) return 1; // n is a perfect square

    // Check if sum of two squares
    for (int i = 1; i <= sqrtN; i++) {
        int rem = n - i * i;
        int sqrtRem = (int) Math.sqrt(rem);
        if (sqrtRem * sqrtRem == rem) return 2;
    }

    // Check if sum of three squares
    for (int i = 1; i <= sqrtN; i++) {
        int rem1 = n - i * i;
        if (rem1 < 0) break;
        int sqrtREM1 = (int) Math.sqrt(rem1);
        for (int j = i; j <= sqrtREM1; j++) {
            int rem2 = rem1 - j * j;
            if (rem2 < 0) break;
            int sqrtRem2 = (int) Math.sqrt(rem2);
            if (sqrtRem2 * sqrtRem2 == rem2) return 3;
        }
    }

    // By Legendre's theorem, all remaining cases require four squares
    return 4;
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i != words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}
